import { readDeliveryLocation, saveDeliveryLocation, localFreightQuote } from './delivery-context.js';
import { readMarketplace, postalRegion } from './marketplace-settings.js';
import { orderDispatch } from './order-model.js';
const deliveryEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const deliveryMoney=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(c/100);
export function locationFieldsMarkup(saved=readDeliveryLocation()){const regions=readMarketplace().regions;return `<label class="field-label">Cidade<select class="panel-input" name="city" required><option value="">Escolha sua cidade</option>${regions.map(r=>`<option ${saved?.city===r.name?'selected':''} value="${deliveryEscape(r.name)}">${deliveryEscape(r.name)}</option>`).join('')}<option ${saved?.city==='Outra cidade'?'selected':''}>Outra cidade</option></select></label><label class="field-label">CEP da sua rua<input class="panel-input" name="cep" inputmode="numeric" autocomplete="postal-code" maxlength="9" placeholder="00000-000" required value="${deliveryEscape(saved?.cep||'')}"></label>`}
export function showLocationChooser(modal){modal('Onde você quer receber?',`<form id="delivery-location-form" class="location-confirmation"><p>Confirme sua cidade e o CEP da sua rua para descobrir as lojas e os produtos disponíveis para você.</p>${locationFieldsMarkup()}<p class="catalog-help">Vamos guardar esta escolha. No cadastro, basta confirmar e completar seu endereço.</p><button class="btn">Confirmar localização</button><p class="delivery-feedback" role="alert"></p></form>`);document.querySelector('#delivery-location-form').onsubmit=e=>{e.preventDefault();try{const data=new FormData(e.target);saveDeliveryLocation(data.get('city'),data.get('cep'));document.querySelector('#modal').close()}catch(err){e.target.querySelector('.delivery-feedback').textContent=err.message}}}
export function shippingResultMarkup(product,subtotal,{incomplete=false}={}){const location=readDeliveryLocation();if(!location)return '<p>Informe seu CEP para consultar entrega e retirada.</p>';const store=readMarketplace().stores.find(s=>s.id===product.store),q=localFreightQuote(product.store,location.cep,subtotal);const dispatch=orderDispatch(new Date().toISOString(),store.cutoff).split('-').reverse().join('/');return `<p class="delivery-destination">Para <strong>${deliveryEscape(location.city)} · ${deliveryEscape(location.cep.replace(/(\d{5})(\d{3})/,'$1-$2'))}</strong></p>${q.delivery?`<article class="freight-option"><div><b>Entrega pela loja</b><p>Despacho previsto para ${dispatch}. Entrega em cerca de ${q.minutes} minutos após a saída.</p></div><strong class="${q.freight===0?'free-freight':''}">${q.freight===0?'Frete grátis':deliveryMoney(q.freight)}</strong></article>`:''}${q.pickup?'<article class="freight-option"><div><b>Retirada na loja</b><p>Aguarde o aviso de pronto para retirada. Sem limite de distância dentro da sua cidade.</p></div><strong>Grátis</strong></article>':''}${!q.delivery&&!q.pickup?'<p class="delivery-unavailable">Esta loja não atende o CEP informado. Altere a localização para consultar outra região.</p>':''}${incomplete?'<p class="catalog-help">Escolha as opções do produto para verificar a condição de frete grátis.</p>':''}<p class="catalog-help">Estimativa demonstrativa. Pagamento confirmado agora; trajeto de teste configurado pela loja. O checkout confirma a gratuidade pelo subtotal de cada loja.</p>`}
export function mountProductShipping({product,getAmount,modal}){if(product.type==='virtual')return;const box=document.querySelector('.shipping-box');if(!box)return;box.innerHTML='<button class="shipping-trigger" data-shipping-open>Calcule seu frete e prazo <span aria-hidden="true">→</span></button><div id="product-freight-preview" aria-live="polite"></div>';refreshProductShipping(product,getAmount);box.querySelector('[data-shipping-open]').onclick=()=>{
  modal('Calcular frete e prazo',`<div class="drawer-content shipping-drawer-content"><form id="product-freight-form">${locationFieldsMarkup()}<button class="btn">Calcular</button><p class="delivery-feedback" role="alert"></p></form><div id="shipping-drawer-result" aria-live="polite">${shippingResultMarkup(product,getAmount().subtotal,getAmount())}</div></div><footer class="drawer-footer"><button class="btn secondary" data-action="close">Voltar ao produto</button></footer>`,'cart');
  const form=document.querySelector('#product-freight-form');form.onsubmit=e=>{e.preventDefault();try{const data=new FormData(form);saveDeliveryLocation(data.get('city'),data.get('cep'));document.querySelector('#shipping-drawer-result').innerHTML=shippingResultMarkup(product,getAmount().subtotal,getAmount());form.querySelector('button').textContent='Calcular novamente';form.querySelector('.delivery-feedback').textContent='';}catch(err){form.querySelector('.delivery-feedback').textContent=err.message}};
 };}
export function refreshProductShipping(product,getAmount){const preview=document.querySelector('#product-freight-preview');if(preview)preview.innerHTML=readDeliveryLocation()?shippingResultMarkup(product,getAmount().subtotal,getAmount()):'<p class="catalog-help">Consulte entrega, retirada e condições de frete grátis para o seu CEP.</p>'}
